const char* lookupVendor(const uint8_t* bssid) {
    uint32_t oui = ((uint32_t)bssid[0] << 16) | ((uint32_t)bssid[1] << 8) | bssid[2];
    size_t low = 0;
    size_t high = sizeof(OUIS) / sizeof(OUIS[0]);
    while (low < high) {
        size_t mid = (low + high) / 2;
        if (OUIS[mid] == oui) return NAMES[NAME_INDEX[mid]];
        if (OUIS[mid] < oui) low = mid + 1; else high = mid;
    }
    return nullptr;
}

